package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class ReportMeasurementsAcceptance {
 static String save(Store store,String table,Map<String,Object> query,boolean shared)throws Exception{try(var db=store.open()){String actor=PlatformFoundationTest.bind(db);String id=SavedReports.save(db,actor,map("name","Measured history","table",table,"query",query,"shared",shared)).get("report_id").toString();db.connection.commit();return id;}}
 static String path(String id){return "/api/openservice/reports/"+id+"/measurements";}
 static Map<String,Object> get(WorkflowSupport h,String id,String query)throws Exception{return TransferAcceptance.result(h.get(path(id)+query,auth("admin")),200);}
 static Map<String,Object> capture(WorkflowSupport h,String id,String key)throws Exception{return TransferAcceptance.result(h.json("POST",path(id),map("key",key),auth("admin")),201);}
 static void change(Store store,String table,String value)throws Exception{try(var db=store.open()){PlatformFoundationTest.bind(db);var record=db.one("SELECT * FROM os_record WHERE \"table\"=? ORDER BY sys_id",table);Service.update(db,table,record,map("amount",value),"admin","admin",null);db.connection.commit();}}
 static void run(WorkflowSupport h)throws Exception{
  String table=ReportFormsAcceptance.seed(h.store),id=save(h.store,table,map("field","amount"),true),key=id();assertEquals(0,objects(get(h,id,"").get("history")).size());assertEquals(true,capture(h,id,key).get("created"));assertEquals(false,capture(h,id,key).get("created"));var first=objects(get(h,id,"").get("history")).getFirst();assertEquals("50",first.get("value"));assertNull(first.get("delta"));assertEquals("100",object(first.get("values")).get("sum"));
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(var row:db.all("SELECT * FROM os_record WHERE \"table\"=?",table))Service.update(db,table,row,map("amount","0.1"),"admin","admin",null);db.connection.commit();}capture(h,id,id());var second=objects(get(h,id,"").get("history")).getLast();assertEquals("0.1",second.get("value"));assertEquals("-49.9",second.get("delta"));assertEquals("-99.8",objects(get(h,id,"?metric=sum").get("history")).getLast().get("delta"));assertEquals("0",objects(get(h,id,"?metric=count").get("history")).getLast().get("delta"));
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(var row:db.all("SELECT * FROM os_record WHERE \"table\"=?",table))Service.update(db,table,row,map("amount",""),"admin","admin",null);db.connection.commit();}capture(h,id,id());assertNull(objects(get(h,id,"").get("history")).getLast().get("value"));assertNull(objects(get(h,id,"").get("history")).getLast().get("delta"));change(h.store,table,"7.25");capture(h,id,id());assertNull(objects(get(h,id,"").get("history")).getLast().get("delta"));new Store(h.environment);assertEquals(4,objects(get(h,id,"").get("history")).size());
  String other=save(h.store,table,map("field","amount"),false);assertEquals(409,h.json("POST",path(other),map("key",key),auth("admin")).statusCode());try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);SavedReports.save(db,actor,id,map("name","Edited","table",table,"query",map("field","amount","q","short_description=Visible"),"shared",true));db.connection.commit();}assertEquals(0,objects(get(h,id,"").get("history")).size());assertEquals(409,h.json("POST",path(id),map("key",key),auth("admin")).statusCode());capture(h,id,id());assertEquals(1,objects(get(h,id,"").get("history")).size());
  try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);var context=ReportMeasurements.context(db,id);for(int n=0;n<105;n++)db.update("INSERT INTO os_report_measurement(measurement_id,report_id,viewer_id,captured_at,definition_hash,result) VALUES(?,?,?,?,?,?)",id(),id,actor,1,context.get("definition_hash"),JSON.writeValueAsString(map("count","1","value_count","1","sum","0.000000000000000001","min","0.000000000000000001","max","0.000000000000000001","average","0.000000000000000001")));db.connection.commit();}capture(h,id,id());assertEquals(100,objects(get(h,id,"").get("history")).size());try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);assertEquals(100,db.count("SELECT COUNT(*) FROM os_report_measurement WHERE report_id=?",id));assertEquals(0,db.count("SELECT COUNT(*) FROM os_report_measurement WHERE measurement_id=?",key));SavedReports.remove(db,actor,id);assertEquals(0,db.count("SELECT COUNT(*) FROM os_report_measurement WHERE report_id=?",id));db.connection.commit();}assertEquals(404,h.get(path(id),auth("admin")).statusCode());
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  String table=ReportFormsAcceptance.seed(h.store),id=save(h.store,table,map("field","amount"),true),path=path(id),ui="/reports/"+id+"/measurements",key=id();h.account("MeasurementOther","admin");h.account("MeasurementReader","reader");capture(h,id,key);assertEquals(0,objects(TransferAcceptance.result(h.get(path,auth("MeasurementOther")),200).get("history")).size());assertEquals(404,h.json("POST",path,map("key",key),auth("MeasurementOther")).statusCode());assertEquals(403,h.get(path,auth("MeasurementReader")).statusCode());assertEquals(403,h.json("POST",path,map("key",id()),auth("MeasurementReader")).statusCode());assertEquals(401,h.get(path,null).statusCode());assertEquals(405,h.json("PUT",path,map(),auth("admin")).statusCode());assertEquals(400,h.get(path+"?metric=invalid",auth("admin")).statusCode());assertEquals(400,h.get(path+"?extra=x",auth("admin")).statusCode());assertEquals(400,h.get(path+"?metric=sum&metric=sum",auth("admin")).statusCode());for(var bad:List.of(map(),map("key","bad"),map("key",id(),"score","1")))assertEquals(400,h.json("POST",path,bad,auth("admin")).statusCode());assertEquals(400,h.json("POST",path+"?metric=sum",map("key",id()),auth("admin")).statusCode());assertEquals(403,h.form(ui,map("key",id()),auth("admin")).statusCode());
  String grouped=save(h.store,table,map("field","amount","group_by","short_description"),false);assertEquals(400,h.get(path(grouped),auth("admin")).statusCode());assertEquals(400,h.json("POST",path(grouped),map("key",id()),auth("admin")).statusCode());
  try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);db.update("UPDATE os_saved_report SET shared=0 WHERE report_id=?",id);db.connection.commit();}assertEquals(404,h.get(path,auth("MeasurementOther")).statusCode());
  Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,table);var denied=new LinkedHashMap<>(original);denied.put("record_roles",map("read",List.of("agent")));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name=?",JSON.writeValueAsString(denied),table);db.connection.commit();}try{assertEquals(403,h.get(path,auth("admin")).statusCode());assertEquals(403,h.json("POST",path,map("key",id()),auth("admin")).statusCode());}finally{try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name=?",JSON.writeValueAsString(original),table);db.connection.commit();}}
  try(var db=h.store.open()){var schema=Service.schema(db,table);object(schema.get("fields")).remove("amount");object(schema.get("field_rules")).remove("amount");db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name=?",JSON.writeValueAsString(schema),table);db.connection.commit();}assertEquals(400,h.get(path,auth("admin")).statusCode());assertEquals(400,h.json("POST",path,map("key",id()),auth("admin")).statusCode());
  try(var db=h.store.open()){db.update("DELETE FROM os_saved_report WHERE report_id=?",id);db.connection.commit();}var env=new org.springframework.mock.env.MockEnvironment();env.merge((org.springframework.core.env.ConfigurableEnvironment)h.environment);env.setProperty("WORK_ENABLED","true");new WorkWorker(new Store(env)).tick();try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_report_measurement WHERE report_id=?",id));}
 }
}
